function InlineMarkdown({ text }) {
  const pattern = /(\*\*[^*]+\*\*|`[^`]+`|!?\[[^\]]+\]\([^\)]+\))/g;
  return text.split(pattern).filter(Boolean).map((part, index) => {
    if (part.startsWith("**") && part.endsWith("**")) return <strong key={index}>{part.slice(2, -2)}</strong>;
    if (part.startsWith("`")) return <code key={index}>{part.slice(1, -1)}</code>;
    const link = part.match(/^(!?)\[([^\]]+)\]\(([^)]+)\)$/);
    if (link) {
      if (link[1]) return <span key={index}>[Изображение: {link[2]}] <a href={link[3]} target="_blank" rel="noreferrer">открыть</a></span>;
      return <a key={index} href={link[3]} target="_blank" rel="noreferrer">{link[2]}</a>;
    }
    return part;
  });
}

function MarkdownAnswer({ source }) {
  const blocks = useMemo(() => {
    const lines = source.replace(/\r/g, "").split("\n");
    const result = [];
    let paragraph = [];
    let list = [];
    let code = [];
    let codeLang = "";
    let table = [];
    const flushParagraph = () => { if (paragraph.length) { result.push({ type: "p", text: paragraph.join(" ") }); paragraph = []; } };
    const flushList = () => { if (list.length) { result.push({ type: list[0].type, items: list.map(x => x.text) }); list = []; } };
    const flushTable = () => { if (table.length) { result.push({ type: "table", rows: table }); table = []; } };
    for (const line of lines) {
      if (line.trim().startsWith("```")) {
        flushParagraph(); flushList(); flushTable();
        if (codeLang !== null) { codeLang = null; code = []; }
        else { result.push({ type: "code", text: code.join("\n"), lang: "" }); code = []; codeLang = ""; }
        continue;
      }
      if (codeLang === null) { code.push(line); continue; }
      if (!line.trim()) { flushParagraph(); flushList(); flushTable(); continue; }
      if (/^\s*\|.*\|\s*$/.test(line)) {
        flushParagraph(); flushList();
        const cells = line.trim().replace(/^\||\|$/g, "").split("|").map(x => x.trim());
        if (!cells.every(x => /^:?-{3,}:?$/.test(x))) table.push(cells);
        continue;
      } else flushTable();
      if (/^\s*---+\s*$/.test(line)) { flushParagraph(); flushList(); result.push({ type: "hr" }); continue; }
      const heading = line.match(/^\s{0,3}(#{1,4})\s+(.+)$/);
      if (heading) { flushParagraph(); flushList(); result.push({ type: "heading", level: heading[1].length, text: heading[2] }); continue; }
      const bullet = line.match(/^\s*[-*+]\s+(.+)$/);
      const numbered = line.match(/^\s*\d+[.)]\s+(.+)$/);
      if (bullet || numbered) {
        flushParagraph();
        const type = bullet ? "ul" : "ol";
        if (list.length && list[0].type !== type) flushList();
        list.push({ type, text: (bullet || numbered)[1] }); continue;
      }
      flushList();
      paragraph.push(line.trim());
    }
    flushParagraph(); flushList(); flushTable();
    if (codeLang === null && code.length) result.push({ type: "code", text: code.join("\n") });
    return result;
  }, [source]);

  return <div className="answer-content">{blocks.map((block, i) => {
    if (block.type === "p") return <p key={i}><InlineMarkdown text={block.text} /></p>;
    if (block.type === "heading") { const Tag = `h${Math.min(block.level + 1, 6)}`; return <Tag key={i}><InlineMarkdown text={block.text} /></Tag>; }
    if (block.type === "ul" || block.type === "ol") { const Tag = block.type; return <Tag key={i}>{block.items.map((item,j)=><li key={j}><InlineMarkdown text={item} /></li>)}</Tag>; }
    if (block.type === "code") return <pre key={i}><code>{block.text}</code></pre>;
    if (block.type === "hr") return <hr key={i} />;
    if (block.type === "table") return <div className="table-scroll" key={i}><table><tbody>{block.rows.map((row,j)=><tr key={j}>{row.map((cell,k)=> j===0 ? <th key={k}><InlineMarkdown text={cell}/></th> : <td key={k}><InlineMarkdown text={cell}/></td>)}</tr>)}</tbody></table></div>;
    return null;
  })}</div>;
}

function shuffleArray(array) {
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

export default function App() {
  const [activeSectionId, setActiveSectionId] = useState("linux");
  const [flashIndex, setFlashIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);
  const [randomOrder, setRandomOrder] = useState(false);
  const activeSection = sections.find(section => section.id === activeSectionId) || sections[0];
  const cards = useMemo(() => randomOrder ? shuffleArray(activeSection.cards) : activeSection.cards, [activeSection, randomOrder]);
  const currentCard = cards[Math.min(flashIndex, cards.length - 1)];
  const selectSection = id => { setIsFlipped(false); setActiveSectionId(id); setFlashIndex(0); setRandomOrder(false); };
  const move = delta => { setIsFlipped(false); setFlashIndex(index => (index + delta + cards.length) % cards.length); };
  const shuffle = () => { setIsFlipped(false); setFlashIndex(0); setRandomOrder(true); };

  return <div className="app"><main className="content"><section className="flash-section">
    <div className="section-navigation">{sections.map(section => <button key={section.id} className={`section-button ${activeSectionId === section.id ? "active" : ""}`} onClick={() => selectSection(section.id)}>{section.name}</button>)}</div>
    <div className="counter">{activeSection.name} · Вопрос {flashIndex + 1} из {cards.length}</div>
    {currentCard && <div className={`flash-card ${isFlipped ? "flipped" : ""}`} onClick={() => setIsFlipped(value => !value)} role="button" tabIndex={0} onKeyDown={e => { if (e.key === "Enter" || e.key === " ") setIsFlipped(value => !value); }}>
      <div className="flash-card-inner"><div className="flash-card-front"><span className="card-title">ВОПРОС</span><h1>{currentCard.question}</h1><p className="click-text">Нажми на карточку, чтобы увидеть ответ</p></div>
        <div className="flash-card-back"><span className="card-title">ОТВЕТ</span><MarkdownAnswer source={currentCard.answer} /></div></div></div>}
    <div className="flash-controls"><button onClick={() => move(-1)}>← Назад</button><button onClick={() => move(1)}>Следующая →</button><button onClick={shuffle}>Перемешать</button></div>
  </section></main></div>;
}
